<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class AccountIp extends Model { public const RESOURCE_NAME = 'account_ip'; protected bool $immutableDates = true; protected $table = 'dezerx_account_ips'; protected $guarded = ['id']; protected $casts = [ 'user_id' => 'int', 'registered' => 'bool', ]; public static array $validationRules = [ 'user_id' => 'required|int|exists:users,id', 'ip' => 'required|string|max:45', ]; public function owner(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } } 